function account_page_start(string $title,string $current,string $eyebrow,string $heading,string $accent='',string $subtitle='',?array $accountUser=null): void {
    $accountUser??=current_user();$storeName=store_runtime_name();$pageTitle=htmlspecialchars(store_t($title).' · '.$storeName,ENT_QUOTES,'UTF-8');$username=htmlspecialchars((string)($accountUser['username']??'Account'),ENT_QUOTES,'UTF-8');
    $monogram='';foreach((preg_split('/[^A-Za-z0-9]+/',trim($storeName))?:[]) as $part){if($part==='')continue;$monogram.=strtoupper(substr($part,0,1));if(strlen($monogram)>=2)break;}if($monogram==='')$monogram='S';
    $navState=['notifications_enabled'=>false,'notification_unread'=>0,'support_unread_enabled'=>false,'support_unread'=>0,'global_unread'=>0,'has_unread'=>false,'notification_href'=>route_url('notifications.php')];$uid=(int)($accountUser['id']??0);if($uid>0){try{$navState=\App\Support\ServiceFactory::navigationState(db())->forUser($uid,false,null,web_notification_excluded_types_for_user($accountUser));}catch(\Throwable){}}
    $links=['overview'=>['Overview',route_url('dashboard.php')],'orders'=>['Orders',route_url('account-orders.php')],'addresses'=>['Addresses',route_url('account-addresses.php')],'wishlist'=>['Wishlist',route_url('wishlist.php')],'support'=>['Support',route_url('support.php')],'security'=>['Settings',route_url('account-security.php')]];
    if(!store_module_enabled('wishlist'))unset($links['wishlist']);
    $currentLabel=store_t($links[$current][0]??$title);$desktopCollapsed=($_COOKIE['auraa_account_sidebar_collapsed']??'')==='1';
web_emit_server_timing('account');
?>
